={{ (() => {
  const b = $('Job Post Webhook').item.json.body || {};
  return [
    `title: ${b.title ?? ''}`,
    `description: ${b.description ?? ''}`,
    `education_level: ${b.education_level ?? ''}`,
    `employment_type: ${b.employment_type ?? ''}`,
    `location: ${b.location ?? ''}`,
    `salary_type: ${b.salary_type ?? ''}`,
    `skills_required: ${Array.isArray(b.skills_required) ? b.skills_required.join(', ') : (b.skills_required ?? '')}`,
    `company_name: ${b.company_name ?? ''}`,
    `hide_company_name: ${b.hide_company_name ?? false}`,
    `key_responsibilities: ${Array.isArray(b.key_responsibilities) ? b.key_responsibilities.join(', ') : (b.key_responsibilities ?? '')}`,
    `experience_level: ${b.experience_level?.level ?? ''}`
  ].join('\n');
})() }}

